<?php
/** Two visible sheets, each with six independently expandable GB tables. */
function buildBiayaInputTemplate(string $period,array $slotsPerGb=[]): \PhpOffice\PhpSpreadsheet\Spreadsheet {
    if(!preg_match('/^(20\d{2})-(0[1-9]|1[0-2])$/D',$period,$match))throw new InvalidArgumentException('Periode BIAYA tidak valid.');
    $year=(int)$match[1];$month=(int)$match[2];$months=['JANUARI','FEBRUARI','MARET','APRIL','MEI','JUNI','JULI','AGUSTUS','SEPTEMBER','OKTOBER','NOVEMBER','DESEMBER'];$targetName=$year===2025?'TARGET ROLLING':'TARGET';$book=new \PhpOffice\PhpSpreadsheet\Spreadsheet();$book->removeSheetByIndex(0);$book->getDefaultStyle()->getFont()->setName('Calibri')->setSize(11);
    foreach([$targetName,'REALISASI'] as $name){$sheet=new \PhpOffice\PhpSpreadsheet\Worksheet\Worksheet($book,$name);$book->addSheet($sheet);$actual=$name==='REALISASI';
        foreach([1=>'BIAYA '.$name.' TAHUN '.$year.' — Rp (000)',2=>'PERIODE LAPORAN: '.$months[$month-1].' '.$year,3=>$actual?'Kategori, nomor, dan nama produk mengikuti sheet '.$targetName.'. Isi nilai realisasi bulanan pada sel kuning.':'Isi kategori, nomor produk, nama produk, dan nilai bulanan. EXIS = Existing; D = New Product.',4=>'Satu tabel per GB. Baris produk boleh ditambah/dikurangi sebelum TOTAL GB; nomor produk unik dalam GB.'] as $r=>$label){$sheet->setCellValue('A'.$r,$label);$sheet->mergeCells('A'.$r.':P'.$r);}
        $sheet->getStyle('A1')->getFont()->setBold(true)->setSize(18);$sheet->getRowDimension(1)->setRowHeight(36);$sheet->getStyle('A2:P4')->getFont()->getColor()->setARGB('FF64748B');$sheet->getStyle('A3:P4')->getAlignment()->setWrapText(true);$sheet->getRowDimension(3)->setRowHeight(32);$sheet->getRowDimension(4)->setRowHeight(32);
        $title=5;foreach(range(1,6) as $gb){$count=max(30,(int)($slotsPerGb[$gb]??30));$header=$title+1;$first=$header+1;$last=$first+$count-1;$total=$last+1;
            $sheet->setCellValue('A'.$title,'GB '.$gb);$sheet->mergeCells('A'.$title.':P'.$title);$sheet->getStyle('A'.$title.':P'.$title)->getFill()->setFillType('solid')->getStartColor()->setARGB('FF345C50');$sheet->getStyle('A'.$title)->getFont()->setBold(true)->getColor()->setARGB('FFFFFFFF');$sheet->getRowDimension($title)->setRowHeight(28);
            foreach(['GB','KATEGORI','NO. PRODUK','NAMA PRODUK',...$months] as $c=>$label)$sheet->setCellValue([$c+1,$header],$label);$sheet->getStyle('A'.$header.':P'.$header)->getFill()->setFillType('solid')->getStartColor()->setARGB('FF29354A');$sheet->getStyle('A'.$header.':P'.$header)->getFont()->setBold(true)->getColor()->setARGB('FFFFFFFF');$sheet->getRowDimension($header)->setRowHeight(32);
            $sheet->getStyle('B'.$first.':P'.$last)->getFill()->setFillType('solid')->getStartColor()->setARGB('FFFFF8DD');
            for($r=$first;$r<=$last;$r++){$sheet->setCellValue('A'.$r,$gb);$sheet->getRowDimension($r)->setRowHeight(24);if($actual)foreach(['B','C','D'] as $col)$sheet->setCellValue($col.$r,"='".$targetName."'!".$col.$r);}
            $category=(new \PhpOffice\PhpSpreadsheet\Cell\DataValidation())->setType('list')->setFormula1('"EXIS,D"')->setAllowBlank(true)->setShowDropDown(true)->setShowErrorMessage(true);$sheet->setDataValidation('B'.$first.':B'.$last,$category);
            $numeric=(new \PhpOffice\PhpSpreadsheet\Cell\DataValidation())->setType('decimal')->setOperator('between')->setFormula1('-999999999999999')->setFormula2('999999999999999')->setAllowBlank(true)->setShowErrorMessage(true)->setErrorStyle('stop')->setError('Isi angka atau biarkan kosong.');$sheet->setDataValidation('E'.$first.':P'.$last,$numeric);
            if($actual){$sheet->getStyle('B'.$first.':D'.$last)->getFill()->getStartColor()->setARGB('FFEAF2FF');$sheet->getStyle('B'.$first.':D'.$last)->getNumberFormat()->setFormatCode('0;-0;;@');}
            $sheet->setCellValue('A'.$total,'TOTAL GB '.$gb);$sheet->mergeCells('A'.$total.':D'.$total);foreach(range('E','P') as $col)$sheet->setCellValue($col.$total,'=SUM('.$col.$first.':'.$col.$last.')');$sheet->getStyle('A'.$total.':P'.$total)->getFill()->setFillType('solid')->getStartColor()->setARGB('FFEAF2FF');$sheet->getStyle('A'.$total.':P'.$total)->getFont()->setBold(true);$sheet->getStyle('E'.$first.':P'.$total)->getNumberFormat()->setFormatCode('#,##0;[Red](#,##0);0');$sheet->getStyle('A'.$header.':P'.$total)->getBorders()->getAllBorders()->setBorderStyle('thin')->getColor()->setARGB('FFE1E5EB');$title=$total+3;
        }
        foreach(['A'=>8,'B'=>13,'C'=>14,'D'=>36] as $col=>$width)$sheet->getColumnDimension($col)->setWidth($width);foreach(range('E','P') as $col)$sheet->getColumnDimension($col)->setWidth(16);$sheet->setShowGridlines(false);$sheet->freezePane('E7');$sheet->getPageSetup()->setOrientation('landscape')->setFitToWidth(1)->setFitToHeight(0)->setPrintArea('A1:P'.$total);
    }
    $meta=new \PhpOffice\PhpSpreadsheet\Worksheet\Worksheet($book,'_TEMPLATE');$book->addSheet($meta);$meta->fromArray([['KONIMEX_BIAYA_V2'],['BIAYA'],[$year],[$period]]);$meta->setSheetState('hidden');$book->setActiveSheetIndex(0);return $book;
}
function biayaGroupLayouts(\PhpOffice\PhpSpreadsheet\Worksheet\Worksheet $sheet,array $headers): array {
    $norm=static fn($v)=>strtoupper(trim(preg_replace('/\s+/u',' ',(string)$v)));$titles=[];$totals=[];
    foreach($sheet->getCellCollection()->getCoordinates() as $address){$value=$sheet->getCell($address)->getValue();if(!is_string($value))continue;$label=$norm($value);if(!preg_match('/^(TOTAL\s+)?GB\s*([1-6])$/D',$label,$match))continue;[, $row]=\PhpOffice\PhpSpreadsheet\Cell\Coordinate::coordinateFromString($address);$gb=(int)$match[2];if(!empty($match[1])){if(isset($totals[$gb]))throw new InvalidArgumentException('TOTAL GB '.$gb.' berulang di '.$sheet->getTitle().'.');$totals[$gb]=$row;}else{if(isset($titles[$gb]))throw new InvalidArgumentException('Tabel GB '.$gb.' berulang di '.$sheet->getTitle().'.');$titles[$gb]=$row;}}
    $layouts=[];foreach(range(1,6) as $gb){$title=$titles[$gb]??null;$total=$totals[$gb]??null;if($title===null||$total===null||$total<=$title)throw new InvalidArgumentException('Judul dan TOTAL GB '.$gb.' belum lengkap di '.$sheet->getTitle().'.');foreach($titles as $other=>$row)if($other!==$gb&&$row>$title&&$row<$total)throw new InvalidArgumentException('TOTAL GB '.$gb.' harus berada sebelum tabel GB berikutnya.');$matches=array_values(array_filter($headers,static fn($layout)=>$layout['header']>$title&&$layout['header']<$total));if(count($matches)!==1)throw new InvalidArgumentException('Header tabel GB '.$gb.' tidak lengkap atau berulang di '.$sheet->getTitle().'.');$layouts[]=$matches[0]+['gb'=>$gb,'title'=>$title,'first'=>$matches[0]['header']+1,'last'=>$total-1,'total'=>$total];}return $layouts;
}
